import json,sqlite3;from pathlib import Path
r=Path(__file__).resolve().parents[1];j=json.loads((r/'registry/registry.json').read_text());assert len({x['id'] for x in j['algorithms']})==len(j['algorithms']);assert len({x['id'] for x in j['namespaceBindings']})==len(j['namespaceBindings']);d=sqlite3.connect(r/'registry/registry.sqlite');assert d.execute('select count(*) from algorithms').fetchone()[0]==len(j['algorithms']);assert d.execute('select count(*) from namespace_bindings').fetchone()[0]==len(j['namespaceBindings']);print('PASS',len(j['algorithms']),len(j['namespaceBindings']),len(j['relationships']))